entries[96252] = { ["name"] = "Flüchtiger Alchemistenstein", ["text"] = "Wirken in 1.5 sek. 5\nReagenzien:\nFlüchtiges Leben (50), Aschenblüte (12), Herzblüte (24)\nFlüchtiger Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: [Alchemist Stone] (1)Schmuck\n+301 Stärke\nErhöht Eure Meisterschaftswertung um + 194.\n\nRoter Sockel\nSockelbonus: + 10 Stärke\n\n80\nBenötigt Alchemie\n(500)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[96253] = { ["name"] = "Lebhafter Alchemistenstein", ["text"] = "Wirken in 1.5 sek. 5\nReagenzien:\nFlüchtiges Leben (50), Aschenblüte (24), Herzblüte (12)\nLebhafter Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: [Alchemist Stone] (1)Schmuck\n+301 Beweglichkeit\nErhöht Eure kritische Trefferwertung um + 194.\n\nRoter Sockel\nSockelbonus: + 10 Beweglichkeit\n\n80\nBenötigt Alchemie\n(500)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
entries[96254] = { ["name"] = "Leuchtender Alchemistenstein", ["text"] = "Wirken in 1.5 sek. 5\nReagenzien:\nFlüchtiges Leben (50), Aschenblüte (8), Azsharas Schleier (20), Herzblüte (8)\nLeuchtender Alchemistenstein\nWird beim Aufheben gebunden\nEinzigartig anlegbar: [Alchemist Stone] (1)Schmuck\n+301 Intelligenz\nErhöht Eure Tempowertung um + 194.\n\nRoter Sockel\nSockelbonus: + 10 Intelligenz\n\n80\nBenötigt Alchemie\n(500)\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"" }
